architecture.h4_f:
msg = CBOR{v:1, текст, ответ_на, отправленный_ат}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, текст, ответ_кому?, идентификатор темы?, упоминания?, send_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
провод = CBOR{
  в: 1,
  зашифрованный текст: hex(ct), // переменная длина
  одноразовый номер: шестнадцатеричный (12 Б),
  sender_pseudo: шестнадцатеричный (16 Б),
  send_at: unix_ms
}

cryptoWire.h5_f:
внешний = CBOR{
  исходный_узел: hex32,
  целевой_пользователь: int64,
  внутренний_шифрованный текст: байты,
  внутренний_нонсе: байты,
  send_at: unix_ms
}
сиг = Ed25519-Sign (source_priv, внешний)
POST /federation/deliver {конверт: внешний, подпись: hex64 }

auth.h1_f:
POST /api/аутентификация/регистрация
  {имя пользователя, пароль, x25519_public_key, display_name, телефон?, адрес электронной почты?, avatar_emoji }

Ответ 201 Создано:
  { access_token,refresh_token, user_id, имя пользователя, ... }

auth.h3_f:
Полезная нагрузка access_token:
  { sub: user_id, jti: device_id, тип: «доступ», опыт: сейчас + 15 минут }
Полезная нагрузка обновить_токен:
  { sub: user_id, jti: device_id, тип: «обновить», exp: now + 30d }

HS256 подписан 64-байтовым секретом узла из .env.

auth.h4_f:
Register_begin(): вызов = rand(32)
                    options = { rp.id, user.id, pubKeyCredParams, вызов }
                    варианты возврата

Register_finish (аттестация):
  проверить аттестацию по TPM / Secure Enclave root CA
  магазин { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-битный шестнадцатеричный код, ttl: 60 }
QR payload = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → зарегистрировано новое устройство; JWT вернулись.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 шестнадцатеричных значения
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Разветвленный кадр: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, send_at} }

files.h2_f:
init POST /api/files/resumable/init {имя файла, размер, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct байт>
            ← 204
завершить POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, URL}
TTL на незаконченном: 24 часа

files.h4_f:
Deny_list = {
  "приложение/x-dosexec",
  "приложение/x-sharedlib",
  "приложение/x-mach-двоичный",
}
если Magic.from_buffer(buf[:1024]) в Deny_list: вернуть 415

presence.h1_f:
клиент: при первом нажатии клавиши → отправить {type: «t», состояние: «start»}
         больше не отправляется в течение 3 с, если состояние не изменится
         10 секунд после последнего нажатия клавиши → отправить {type:"t", state:"stop"}
приемник: автостоп через 10 с после последнего «запуска», если «стоп» не поступил

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS трансляция {type:"c", kind:"invite", call_id}
WS трансляция {тип:"c", вид:"предложение", sdp}
WS трансляция {тип:"c", вид:"ответ", sdp}
WS трансляция {тип:"c", вид:"кандидат",лед} × N
POST /api/calls/{call_id}/end

federation.h2_f:
конверт = {
  исходный_узел: hex32,
  целевой_пользователь: int64,
  внутренний_шифрованный текст: байты,
  внутренний_нонсе: байты,
  send_at: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(конверт))
POST /federation/deliver {конверт, подпись}

gossip.h3_f:
реклама = {pubkey, конечная точка, рекламируемый_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(реклама))
полезная нагрузка для сплетен: [..., {ad, sig}, ...]

получатель: проверьте подпись по ad.pubkey → сохраните, если все в порядке
дополнительно: PoW из 2^18 ведущих нулей на {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template с {
  случайный = наш случайный,
  имя_сервера = наше имя хоста (или завернутое в ECH),
  session_id = идентификатор нашей сессии,
}
JA4 = t13d_xxxx_xxxx_xxxx (соответствует текущей стабильной версии Chrome)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {имя: x.vortexx.sol}
ECH: ClientHello.extensions += Encrypt_sni(public_key_from_HTTPS_record)
DGA: домен(t) = base32( SHA256(seed ∥ YYYY-MM-DD))[:16] + ".example"

push.h4_f:
iOS NSE: DidReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Веб SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
инструмент = знак_инструмент
input = дерево исходного кода, ключи/release.key
манифест = {
  версия: "0.1.0",
  встроенный_ат: unix_ms,
  файлы: [{путь, sha256, размер}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(манифест))
вывод = INTEGRITY.sig.json = {manifest, Signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
create: POST /api/bots {имя пользователя, display_name, код}
          → {bot_id, токен, публичный ключ}
запуск: в процессе (сопрограмма внутри узла)
      OR внешний (длинный опрос /api/bots/{id}/updates, аутентификация по токену)
сообщение: {текст, подпись: Ed25519-Sign(bot_priv, canonical_msg)}

